            r"(?i)\b(?:reuters/?michigan|university of michigan|michigan index of consumer sentiment|"
            r"consumer sentiment survey|consumer sentiment index|index of consumer sentiment|"
            r"sentiment index)\b"
        )
        exclude_pat = re.compile(r"(?i)\b(?:conference board|consumer confidence)\b")

        reading_pats = [
            re.compile(
                r"(?i)\b(?:has\s+|had\s+)?(?:declined(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"fallen(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"fell(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"rose(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"stood at|standing at|"
                r"moving(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+up\s+to|"
                r"moved(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+up\s+to|"
                r"moved(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+higher,\s+reaching|"
                r"trended higher,\s+reaching|reaching)\s+"
                r"(?:just|only|about|roughly|around|approximately|nearly|close to|slightly|modestly|marginally|"
                r"somewhat|a bit|a record low of|a record high of|a multi-year low of|a multi-year high of|"
                r"a 14-year high of|a 18-year high of)?\s*"
                r"\d+(?:\.\d+)?(?:\s+(?:in|during|by|at|as of|for)\s+[^.;,\n]{1,40})?"
            ),
            re.compile(
                r"(?i)\b(?:reached)\s+(?:a\s+)?(?:record low|record high|multi-year low|multi-year high|"
                r"14-year high|18-year high)\s+of\s+\d+(?:\.\d+)?"
            ),
        ]

        def best_phrase(block: str) -> str:
            block = norm(block)
            if not block:
                return ""
            best = ""
            best_pos = -1
            for pat in reading_pats:
                for m in pat.finditer(block):
                    if m.start() >= best_pos:
                        best_pos = m.start()
                        best = norm(m.group(0).rstrip(" ,;:"))
            return best

        def scan_text(text: str) -> list[str]:
            text = norm(text)
            if not text or not trigger_pat.search(text):
                return []

            block = text
            exclude_match = exclude_pat.search(block)
            if exclude_match:
                block = block[: exclude_match.start()]

            out: list[str] = []
            for pat in reading_pats:
                for m in pat.finditer(block):
                    phrase = norm(m.group(0).rstrip(" ,;:"))
                    if phrase:
                        out.append(phrase)
            return out

        def scan_windows(items: list[dict], key: str, meta_key: str, window_size: int = 12) -> list[dict]:
            ordered = [item for item in items if item.get(key)]
            best_hit: dict | None = None
            best_idx = 10**9
            for idx in range(len(ordered)):
                window = ordered[idx : idx + window_size]
                lead_block = norm(" ".join((item.get(key) or "") for item in window[:2]))
                if not lead_block or not trigger_pat.search(lead_block):
                    continue
                block = norm(" ".join((item.get(key) or "") for item in window))

                exclude_match = exclude_pat.search(block)
                if exclude_match:
                    block = block[: exclude_match.start()]

                phrase = best_phrase(block)
                if phrase:
                    if idx < best_idx:
                        best_idx = idx
                        first = window[0]
                        span = {"text": phrase}
                        if first.get("page_no") is not None:
                            span["page_no"] = first.get("page_no")
                        if first.get(meta_key) is not None:
                            span[meta_key] = first.get(meta_key)
                        best_hit = span
            return [best_hit] if best_hit else []

        ordered_paragraphs = sorted(
            [item for item in (doc.get("paragraphs") or []) if item.get("text")],
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("paragraph_no", 10**9),
            ),
        )
        ordered_lines = sorted(
            [item for item in (doc.get("lines") or []) if item.get("text")],
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("line_no", 10**9),
            ),
        )
        hits = scan_windows(ordered_lines, "text", "line_no", window_size=12)
        if hits:
            return hits

        for item in ordered_paragraphs:
            phrases = scan_text(item.get("text") or "")
            if phrases:
                return [
                    {
                        "text": phrases[-1],
                        "page_no": item.get("page_no"),
                        "paragraph_no": item.get("paragraph_no"),
                    }
                ]

        return []
    except Exception:
        return []

    if spec is None or spec.loader is None:
        raise ValueError(f"Failed to load rule module: {rule_file}")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    for name, value in vars(mod).items():
        if name.startswith("rule_") and callable(value):
            return value
    raise ValueError(f"No function starting with 'rule_' found in {rule_file}")


def _coerce_span(entry: Any) -> dict[str, Any] | None:
    if isinstance(entry, str):
        text = entry.strip()
        return {"text": text} if text else None
    if not isinstance(entry, dict):
        return None
    text = entry.get("text")
    if text is None:
        return None
    text = str(text)
    if not text.strip():
        return None
    coerced = dict(entry)
    coerced["text"] = text
    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )


def _judge_call(
    dataset_name: str,
    question: str,
    ground_truth: Any,
    predicted: Any,
) -> tuple[bool, int, int]:
    if ground_truth is None or predicted is None:
        return False, 0, 0

    model_mod = importlib.import_module("models.gpt54")
    gt_str = json.dumps(ground_truth) if not isinstance(ground_truth, str) else ground_truth
    pred_str = str(predicted)
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {
                "role": "system",
                "content": _JUDGE_SYSTEM_BY_DATASET.get(dataset_name, _JUDGE_SYSTEM_GENERIC),
            },
            {
                "role": "user",
                "content": f"Question: {question}\nGround Truth: {gt_str}\nPredicted: {pred_str}",
            },
        ],
        max_completion_tokens=10,
        temperature=0.0,
    )
    verdict = (response.choices[0].message.content or "").strip().lower()
    usage = response.usage
    return (
        verdict == "correct",
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
    )


def _clean_stderr(stderr: str) -> str:
    lines = [
        line
        for line in stderr.splitlines()
        if line.strip() != "Reading additional input from stdin..."
    ]
    return "\n".join(lines).strip()[:4000]


def _parse_done_output(text: str) -> str | None:
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("AGENTIC_RULE_FULL_DATA_DONE"):
            rest = line[len("AGENTIC_RULE_FULL_DATA_DONE") :].strip()
            if rest.startswith("report="):
                return rest[len("report=") :].strip()
    return None


def _parse_codex_events(jsonl_text: str) -> dict[str, Any]:
    usage_totals = {
        "input_tokens": 0,
        "output_tokens": 0,
        "cached_input_tokens": 0,
        "reasoning_output_tokens": 0,
    }
    thread_id: str | None = None
    error_message: str | None = None
    event_count = 0

    for raw_line in jsonl_text.splitlines():
        raw_line = raw_line.strip()
        if not raw_line:
            continue
        try:
            event = json.loads(raw_line)
        except json.JSONDecodeError:
            continue
        event_count += 1
        if event.get("type") == "thread.started":
            thread_id = event.get("thread_id")
        elif event.get("type") == "turn.completed":
            usage = event.get("usage") or {}
            for key in usage_totals:
                usage_totals[key] += int(usage.get(key) or 0)
        elif event.get("type") in {"error", "turn.failed"}:
            error_message = event.get("message") or str(event.get("error") or "")

    return {
        "usage_totals": usage_totals,
        "thread_id": thread_id,
        "error_message": error_message,
        "event_count": event_count,
    }


